# Tier 0: Core Invariant Preservation (Smoke Depth)
# ---------------------------------------------------------------------------
class TestIdentityLifecycle:
    """Tests the minimal identity creation and verification path."""

    def test_create_identity_returns_valid_keypair(self, identity_manager):
        """Creating an identity must yield a public key that verifies."""
        identity = identity_manager.create_identity()
        assert "public_key" in identity
        assert "private_key" in identity
        # Core invariant: the public key must be self-verifiable
        assert identity_manager.verify_identity(identity["public_key"]) is True

    def test_sign_verify_round_trip(self, identity_manager, sample_data):
        """A signature created by sign() must verify against the same data."""
        identity = identity_manager.create_identity()
        signature = identity_manager.sign(identity["private_key"], sample_data)
        assert identity_manager.verify_signature(
            identity["public_key"], sample_data, signature
        ) is True

    def test_sign_verify_tamper_detection(self, identity_manager, sample_data):
        """A tampered payload must fail verification (invariant: no false positives)."""
        identity = identity_manager.create_identity()
        signature = identity_manager.sign(identity["private_key"], sample_data)
        tampered_data = sample_data + b"X"
        with pytest.raises(InvalidSignatureError):
            identity_manager.verify_signature(
                identity["public_key"], tampered_data, signature
            )


